package dev.sluide.fileviewers.code

import java.nio.file.Path

/** A file that [tool] writes from [source] when [command] runs, e.g. a lock file; edits to it are overwritten. */
internal data class GeneratedFile(
    val tool: String,
    val source: String,
    val command: String,
) {
    /** What a code view's banner says about the file named [name]. */
    fun message(name: String): String =
        "$name is generated by $tool from $source; change the source and run \"$command\" instead of editing this one."
}

/** The generated files a code view points out ([CodeView]), known by their exact name, case-insensitive. */
internal object GeneratedFiles {
    private val byName =
        mapOf(
            "uv.lock" to GeneratedFile("uv", "pyproject.toml", "uv lock"),
            "poetry.lock" to GeneratedFile("Poetry", "pyproject.toml", "poetry lock"),
            "pdm.lock" to GeneratedFile("PDM", "pyproject.toml", "pdm lock"),
            "pipfile.lock" to GeneratedFile("Pipenv", "Pipfile", "pipenv lock"),
            "cargo.lock" to GeneratedFile("Cargo", "Cargo.toml", "cargo update"),
            "package-lock.json" to GeneratedFile("npm", "package.json", "npm install"),
            "yarn.lock" to GeneratedFile("Yarn", "package.json", "yarn install"),
            "pnpm-lock.yaml" to GeneratedFile("pnpm", "package.json", "pnpm install"),
            "gemfile.lock" to GeneratedFile("Bundler", "Gemfile", "bundle install"),
            "composer.lock" to GeneratedFile("Composer", "composer.json", "composer update"),
            ".terraform.lock.hcl" to
                GeneratedFile("Terraform", "required_providers in your .tf files", "terraform init -upgrade"),
        )

    /** The generator of [file], by its name, or `null` if it is no known generated file. */
    fun of(file: Path): GeneratedFile? = file.fileName?.let { byName[it.toString().lowercase()] }
}
